"use strict";(globalThis.webpackChunkztools_docs=globalThis.webpackChunkztools_docs||[]).push([[20406],{23065(o){o.exports=JSON.parse('{"id":"achat","name":"AchatAI","url":"https://achat.aoneahsan.com","platforms":["Web","Android"],"logo":"/ecosystem/achat.svg","card":"Send a file you just made to someone, without swapping phone numbers first.","title":"AchatAI: share with people you choose, no phone number needed","intro":"AchatAI is a messaging app on the web and Android for the people you choose. You find someone by username, invite link or QR code, so a phone number never has to change hands.","sections":[["Why would a ZTools user need it?","You finish something in ZTools: a converted PDF, a QR code, notes from a meeting. Then it has to reach someone. AchatAI lets you find them by username or invite link, not by a number you would rather keep."],["Can I talk to someone without an account?","Yes, in an anonymous room. You can open one without signing up, which suits a quick exchange with someone you will not talk to again."],["Where does it run?","On the web and on Android."]]}')}}]);